//
//  مثال ترقيعة (شيل علامات // من قدام السطور عشان تشتغل):
//    var t = Reflect.FindType("TaleWorlds.CampaignSystem.Hero", "Hero");
//    var m = t.GetMethod("ChangeHeroGold");
//    h.Patch(m, prefix: new HarmonyMethod(typeof(Custom).GetMethod("GoldPrefix")));
//
//    public static void GoldPrefix(ref int __0) { if (__0 > 0) __0 = __0 * 2; }  // فلوس الضعف
//
//  نصايح:
//   - __0 و __1 ... معناها أول وتاني باراميتر في الدالة الأصلية. ref عشان تغيّر قيمته.
//   - return false في Prefix معناها "متكمّلش الدالة الأصلية".
